corporate_design.toad_component_blueprint:
canvas {
  size: 880px 560px;
  fill: #FAF8F5;
  font-family: "Plus Jakarta Sans, sans-serif";
}

>green = #15803D;

rect #teaCard {
  at: center of canvas;
  size: 780px 460px;
  fill: #FFFFFF;
  stroke: #E2E8F0;
  stroke-width: 1px;
  radius: 16px;
}

text #teaHeader {
  at: top left of #teaCard offset 40px 40px;
  content: "ALPENKRÄUTER // HANDGEPFLÜCKT AUF 1.600 M";
  font-size: 13px;
  font-weight: 600;
  color: >green;
}

text #teaTitle {
  at: below #teaHeader offset 14px;
  content: "Wilde Minze & Alpen-Thymian";
  font-size: 30px;
  font-weight: 700;
  color: #1F2937;
}
